/**
 * Standard dishes: one entry per dish as people in London order it, with the names menus use.
 * Agents map each menu item to one of these (its `zh`) when they can; the standard name keys
 * dish search across places and the dish's AI illustration. `description` says what the dish
 * looks like served, for illustration prompts.
 */

export interface DishEntry {
  /** The standard name in simplified Chinese, e.g. '宫保鸡丁'. Unique. */
  zh: string;
  /** The usual English name on London menus, e.g. 'Kung Pao chicken'. */
  en: string;
  /** Other names seen on menus: traditional characters, Cantonese or other romanisations, other English names. */
  aliases: readonly string[];
  /** One of the cuisine values listed below. */
  cuisine: string;
  /** What it looks like served, for an image prompt: one or two short English sentences. */
  description: string;
}

